// The source lock is the only editable compatibility record. Generated files
// are checked in so Go, Docker and the standalone FPK need no runtime checkout.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { resolve } from "node:path";

export async function generate(root, check = false) {
  const lock = JSON.parse(await readFile(resolve(root, "extensions/mdcz-bridge/source-lock.json"), "utf8"));
  if (lock.schema !== 1 || !/^[a-f0-9]{40}$/.test(lock.engine_revision) ||
      !/^\d+\.\d+\.\d+$/.test(lock.engine_version) ||
      !/^[a-f0-9]{64}$/.test(lock.webui_archive_sha256) ||
      lock.repository !== "https://github.com/ShotHeadman/mdcz.git" ||
      !/^\d+\.\d+\.\d+$/.test(lock.bridge_version) ||
      !Number.isInteger(lock.protocol) || lock.protocol < 1 ||
      !Number.isInteger(lock.configuration_version) || lock.configuration_version < 1 ||
      !Array.isArray(lock.capabilities) || !lock.capabilities.length ||
      new Set(lock.capabilities).size !== lock.capabilities.length ||
      lock.capabilities.some((value) => typeof value !== "string" || !/^[a-z-]+$/.test(value)))
    throw new Error("Invalid MDCz source lock");
  const generated = "// Code generated by extensions/mdcz-bridge/generate-compatibility.mjs; DO NOT EDIT.\n";
  const js = generated +
    `export const protocol = ${lock.protocol};\n` +
    `export const engineRevision = ${JSON.stringify(lock.engine_revision)};\n` +
    `export const bridgeVersion = ${JSON.stringify(lock.bridge_version)};\n` +
    `export const configurationVersion = ${lock.configuration_version};\n` +
    `export const requiredCapabilities = Object.freeze(${JSON.stringify(lock.capabilities)});\n`;
  const go = generated + "package mdcz\n\nconst (\n" +
    `\tProtocol             = ${lock.protocol}\n\tEngineRevision       = ${JSON.stringify(lock.engine_revision)}\n` +
    `\tBridgeVersion        = ${JSON.stringify(lock.bridge_version)}\n\tConfigurationVersion = ${lock.configuration_version}\n)\n\n` +
    `var RequiredCapabilities = []string{${lock.capabilities.map(JSON.stringify).join(", ")}}\n`;
  for (const [name, value] of [
    ["extensions/mdcz-bridge/compatibility.generated.mjs", js],
    ["packaging/fnos/app/service/compatibility.mjs", js],
    ["internal/mdcz/version_generated.go", go],
  ]) {
    const path = resolve(root, name);
    if (check) {
      if (await readFile(path, "utf8") !== value) throw new Error(`Stale compatibility file: ${name}`);
    } else await writeFile(path, value);
  }
  return lock;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  await generate(resolve(import.meta.dirname, "../.."), process.argv.includes("--check"));
